    basic=dict(n=n,n_positive=int(X[:,j].sum()),n_reference=int(n-X[:,j].sum()),n_parameters=X.shape[1],rank=rank,df=df)
    if not np.isfinite(y).all() or not np.isfinite(X).all() or rank<X.shape[1] or df<min_df or min(basic['n_positive'],basic['n_reference'])<5:
        return dict(**basic,status='UNAVAILABLE',reason='Incomplete score,rank,group-size,or residual-df gate',effect=np.nan,se=np.nan,CI95_low=np.nan,CI95_high=np.nan,p_value=np.nan,partial_R2=np.nan)
    pinv=np.linalg.pinv(X);beta=pinv@y;res=y-X@beta;hat=np.einsum('ij,ji->i',X,pinv);w=pinv[j];se=np.sqrt(np.sum((w*res/(1-hat))**2));eff=beta[j];q=stats.t.ppf(.975,df);red=np.delete(X,j,axis=1);rred=y-red@(np.linalg.pinv(red)@y);ssered=np.sum(rred*rred)
    return dict(**basic,status='OK',reason='',effect=eff,se=se,CI95_low=eff-q*se,CI95_high=eff+q*se,p_value=2*stats.t.sf(abs(eff/se),df),partial_R2=max(0.,1-np.sum(res*res)/ssered),max_leverage=hat.max())
