# Fixed ridge-logistic leave-one-unit-out comparisons. Recompute gene reference scaling
# excluding the held-out profile, then fit model-variable standardization on training only.
def ridge_logistic(X,y,penalty=1.):
    pen=np.ones(X.shape[1])*penalty;pen[0]=0;beta=np.zeros(X.shape[1]);beta[0]=math.log(y.mean()/(1-y.mean()))
    def value(b):eta=X@b;return np.sum(np.logaddexp(0,eta)-y*eta)+.5*np.sum(pen*b*b)
    for k in range(100):
        eta=X@beta;p=expit(eta);grad=X.T@(p-y)+pen*beta
        if np.max(np.abs(grad))<1e-8:return beta,k+1,np.max(np.abs(grad))
        H=X.T@(X*(p*(1-p))[:,None])+np.diag(pen);step=np.linalg.solve(H,grad);rate=1.;old=value(beta)
        while value(beta-rate*step)>old-1e-4*rate*(grad@step) and rate>1e-8:rate*=.5
        beta-=rate*step
    assert np.max(np.abs(grad))<1e-6,('Ridge convergence',np.max(np.abs(grad)))
    return beta,100,np.max(np.abs(grad))
